-- ─────────────────────────────────────────────────────────────
-- Import Claudia's full training log ("Plantilla de registro") into the app
-- as WORKOUT HISTORY, linked to the WELLNESS plan.
--
-- Run AFTER: seed-wellness-claudia.sql, and AFTER yaczoe@gmail.com registered.
-- Each session (date) becomes one workout; each logged row becomes a set.
-- Missing exercises are auto-created in the catalog so progress charts link up.
-- Idempotent: skips if WELLNESS already has imported workouts.
-- ─────────────────────────────────────────────────────────────
do $$
declare
  uid uuid; pid uuid; wkid uuid; wnotes text; s record;
begin
  select id into uid from users where lower(email) = lower('yaczoe@gmail.com');
  if uid is null then
    raise exception 'No existe usuario yaczoe@gmail.com. Registra la cuenta primero.';
  end if;
  select id into pid from plans where user_id = uid and name = 'WELLNESS' limit 1;

  create temp table reg(ord int, d text, wk text, ex text, grp text, weight numeric, reps int, rir text, note text) on commit drop;

  if pid is not null and exists (select 1 from workouts where user_id = uid and plan_id = pid) then
    raise notice 'WELLNESS ya tiene entrenamientos importados; no se importa de nuevo.';
    return;
  end if;

  -- Create any exercises that are not yet in the catalog (so charts can link).
  select uid, trim(r.ex), (array_agg(r.grp order by r.ord))[1]
  from reg r
  where not exists (
    select 1 from exercises e
    where (e.owner_id is null or e.owner_id = uid) and lower(trim(e.name)) = lower(trim(r.ex))
  )
  group by trim(r.ex);

  -- One workout per (rutina, date), then its sets.
  for s in select distinct wk, d from reg order by d, wk loop
    select string_agg(distinct nullif(note,''), ' · ') into wnotes from reg where wk = s.wk and d = s.d;
      values (uid, s.wk, (s.d || ' 12:00')::timestamptz, pid, coalesce(wnotes,''))
      returning id into wkid;
    select wkid,
      (select e.id from exercises e
        where (e.owner_id is null or e.owner_id = uid) and lower(trim(e.name)) = lower(trim(r.ex))
        order by e.owner_id nulls last limit 1),
      trim(r.ex),
      row_number() over (partition by lower(trim(r.ex)) order by r.ord),
      r.weight, r.reps, nullif(r.rir,'')
    from reg r where r.wk = s.wk and r.d = s.d order by r.ord;
  end loop;

  raise notice 'Importadas % sesiones de WELLNESS.', (select count(distinct (wk,d)) from reg);
end $$;
